OA22 = "LE07 OA 22"
MAT_E = "Este cuaderno, lápiz, un reloj o temporizador y los textos escritos en cada ejercicio. Una persona de tu casa que te escuche en la tarea abierta."

L(OA22, 1,
  MAT_E,
  "Aprenderé a definir el propósito, la audiencia y el tema acotado de una exposición oral antes de prepararla.",
  ["Sé qué es un tema.", "Hablo frente a un grupo pequeño."],
  ["Una exposición oral es un discurso planificado para informar o explicar un tema a una audiencia. Antes de investigar, hay que tomar tres decisiones. El propósito: ¿para qué hablo? (informar, explicar, convencer). La audiencia: ¿quiénes me escuchan y qué saben ya? El tema acotado: ¿qué parte exacta voy a tratar en el tiempo que tengo?",
   "Un tema amplio como «El agua» no cabe en cinco minutos. Acotarlo es elegir un aspecto concreto: «Cómo ahorrar agua al lavarse los dientes». Para acotar, pregúntate: ¿qué parte de este tema puedo explicar bien con ejemplos en el tiempo disponible? Si la respuesta es «poco», el tema es demasiado amplio.",
   "La audiencia determina cómo hablas. A compañeros de 7.º puedes usar términos del curso explicados brevemente. A niños de 1.º necesitas ejemplos cercanos y palabras simples. También decide el tono: más formal ante un adulto invitado, más cercano ante tu curso. Una exposición bien planificada empieza con estas tres decisiones y las anota en una frase: «Quiero explicar [tema] a [audiencia] para que [propósito]»."],
  [("exposición oral", "presentación planificada de un tema a una audiencia"), ("audiencia", "personas que escuchan"), ("tema acotado", "tema reducido a un aspecto que se puede tratar en el tiempo disponible"), ("propósito", "razón por la que se habla, como informar o explicar")],
  [("Acotar un tema", "Tienes 5 minutos. ¿Qué tema es más adecuado: «Los volcanes de Chile» o «Qué es un volcán y por qué Chile tiene muchos»?",
    ["El primero es muy amplio.", "El segundo elige dos aspectos concretos.", "Cabe mejor en 5 minutos."],
    "«Qué es un volcán y por qué Chile tiene muchos»"),
   ("Pensar en la audiencia", "Vas a explicar la fotosíntesis a niños de 1.º. ¿Qué conviene: términos técnicos sin explicar o un ejemplo de una planta que crece al sol?",
    ["Pienso en lo que saben los niños.", "No conocen los términos técnicos.", "Un ejemplo cercano los ayuda."],
    "Un ejemplo de una planta que crece al sol")],
  [("Elegir un tema tan amplio que no cabe en el tiempo.", "Se piensa que mientras más se diga, mejor.", "Acota el tema a un aspecto que puedas explicar bien."),
   ("Preparar sin pensar en la audiencia.", "Se habla igual a cualquiera.", "Adapta el vocabulario y los ejemplos a quienes escuchan.")],
  ([E("¿Cuál tema es más acotado: «El agua» o «Cómo ahorrar agua al lavarse los dientes»?", "Cómo ahorrar agua al lavarse los dientes", "Elige un aspecto concreto."),
    E("¿Qué propósito tiene una exposición que explica cómo funciona el reciclaje: explicar o contar un chiste?", "Explicar", "Su fin es dar a entender un proceso."),
    E("¿Quién es la audiencia de una exposición?", "Las personas que escuchan", "A ellas se dirige el discurso.")],
   [E("Tienes 4 minutos. ¿Qué tema cabe mejor: «La historia de todos los países» o «Cómo se forma la lluvia»?", "Cómo se forma la lluvia", "Es acotado y explicable en poco tiempo."),
    E("Hablas a niños de 1.º sobre las abejas. ¿Qué conviene: palabras simples o muchos términos técnicos?", "Palabras simples", "Se adapta a la audiencia."),
    E("¿Cuál frase resume bien la planificación: «Quiero explicar cómo ahorrar agua a mi curso para que lo practiquen» o «Voy a hablar de agua»?", "Quiero explicar cómo ahorrar agua a mi curso para que lo practiquen", "Incluye tema, audiencia y propósito.")],
   [arith("Tu exposición dura 7 minutos. Dedicas 1 minuto entre inicio y cierre y repartes el resto en 3 ideas iguales. ¿Cuántos minutos corresponden a cada idea?", "(7-1)//3", "Se resta el minuto de inicio y cierre y se divide entre tres."),
    E("Presentas ante tu curso una exposición sobre los volcanes. ¿Cuál es la audiencia: tu curso o tu profesor solamente?", "Tu curso", "Es quien escucha la exposición."),
    E("¿Cuál tema NO está acotado: «El mar», «Las mareas» o «Por qué suben y bajan las mareas»?", "El mar", "Es el más amplio.")],
   [E("Dos estudiantes preparan una exposición de 5 minutos. Ana elige «Los animales». Beto elige «Cómo se camufla un camaleón». ¿Quién acotó mejor su tema?", "Beto", "Eligió un aspecto concreto."),
    E("Si la audiencia son adultos invitados, ¿qué tono conviene: formal o cercano como con amigos?", "Formal", "La situación lo pide.")],
   [E("Tienes 3 minutos para explicar «Qué es el reciclaje». Una opción es incluir la historia del reciclaje en cinco continentes; otra, explicar tres materiales reciclables. ¿Cuál es más viable?", "Explicar tres materiales reciclables", "Cabe en el tiempo."),
    E("Ya decidiste el propósito y la audiencia de tu exposición. ¿Cuántas decisiones previas te faltan según la clase?", "1", "Falta acotar el tema.")]),
  [E("Tu curso prepara una exposición sobre reciclaje para niños de 1.º. ¿Qué ejemplo conviene: «cómo separar la basura de tu casa en tres bolsas» o «la normativa de residuos»?", "Cómo separar la basura de tu casa en tres bolsas", "Es cercano y simple para esa audiencia.")],
  [E("¿Qué significa acotar un tema?", "Reducirlo a un aspecto concreto", "Así cabe en el tiempo."),
   E("¿Quién determina cómo hablas: la audiencia o el reloj?", "La audiencia", "Define vocabulario y ejemplos."),
   E("¿Qué propósitos se mencionan en la clase?", "Informar, explicar o convencer", "Son las razones para hablar.")],
  ("Elige uno de estos temas amplios: «Los animales», «El clima», «Los deportes». Escribe: 1) un tema acotado para 5 minutos; 2) tu audiencia; 3) tu propósito; 4) la frase «Quiero explicar... a... para que...».",
   "Tema amplio: el clima. Acotado: cómo se forman las nubes. Audiencia: mi curso de 7.º. Propósito: explicar. Frase: Quiero explicar cómo se forman las nubes a mi curso para que entendamos de dónde viene la lluvia.",
   ["acota un tema realista", "define una audiencia concreta", "usa la frase completa"], ["cuatro respuestas"], ["tema todavía amplio", "audiencia vaga como «todos»"], "Cuéntaselo a otra persona y pregúntale si el tema cabe en 5 minutos."),
  "Elige un tema que te guste y acótalo en una frase.",
  "Prepara la misma planificación para dos audiencias distintas y compara qué cambias.")

L(OA22, 2,
  MAT_E,
  "Aprenderé a verificar la información que usaré: elegir fuentes confiables, contrastar datos y detectar señales de poca fiabilidad.",
  ["Acoto mi tema.", "Distingo hechos y opiniones."],
  ["Una exposición con información falsa pierde su valor. Una información fidedigna es la que viene de una fuente confiable y se puede comprobar. Para evaluar una fuente, revisa: ¿tiene autor o institución conocida?, ¿tiene fecha, y es reciente cuando el tema cambia?, ¿explica de dónde sacó los datos?, ¿usa un lenguaje objetivo o exagerado?",
   "Señales de alerta: no tiene autor ni fecha, usa exclamaciones y palabras como «increíble» o «secreto», afirma cosas absolutas («siempre», «nunca») o solo da opiniones. Un buen hábito es contrastar: buscar el mismo dato en al menos dos fuentes independientes. Si coinciden, el dato es más confiable. Si no coinciden, investiga una tercera o revisa quién tiene mejor respaldo.",
   "Anota siempre de dónde sacaste cada dato: autor o institución, título y fecha. Así puedes nombrar tus fuentes en la exposición y responder preguntas. Recuerda que investigar antes de hablar muestra seriedad: un dato verificado se dice con seguridad y se defiende con una fuente."],
  [("fuente", "lugar o persona de donde viene la información"), ("fidedigna", "digna de confianza porque se puede comprobar"), ("contrastar", "comparar la misma información en dos o más fuentes"), ("sesgo", "inclinación que hace ver solo una parte de las cosas")],
  [("Evaluar una fuente", "Fuente A (de ejemplo): «Informe del Observatorio Costero, 2024: el nivel del mar subió 3 milímetros en un año». Fuente B (de ejemplo): «¡Increíble secreto! ¡El mar sube sin parar!». ¿Cuál es más confiable?",
    ["A tiene institución, fecha y dato medible.", "B usa exclamaciones y no da origen.", "A es más confiable."],
    "La fuente A"),
   ("Contrastar", "Dos fuentes de ejemplo dan 3 milímetros y la tercera da 30. ¿Qué haces?",
    ["Veo que dos coinciden.", "La tercera difiere mucho.", "Reviso quién tiene mejor respaldo antes de usar el dato."],
    "Reviso el respaldo de la tercera antes de usar el dato")],
  [("Usar la primera página que aparece.", "Se cree que lo primero es lo mejor.", "Evalúa la fuente antes de usarla."),
   ("Usar un dato sin anotar la fuente.", "Después no se puede comprobar.", "Anota autor o institución, título y fecha.")],
  ([E("¿Qué fuente tiene institución, fecha y dato medible: «Informe del Observatorio Costero, 2024» o «Un secreto increíble»?", "Informe del Observatorio Costero, 2024", "Tiene origen identificable."),
    E("¿Qué significa contrastar: comparar fuentes o copiar una sola?", "Comparar fuentes", "Busca coincidencias entre fuentes."),
    E("¿Un texto lleno de exclamaciones y sin autor es más o menos confiable?", "Menos confiable", "Es una señal de alerta.")],
   [E("¿Qué debes anotar de cada fuente: autor o institución, título y fecha, o solo el título?", "Autor o institución, título y fecha", "Permite comprobar y citar."),
    E("Dos fuentes de ejemplo dicen que un río mide 120 kilómetros y una tercera, 12. ¿Cuántas fuentes coinciden?", "2", "Dos dicen 120 kilómetros."),
    E("¿«El mejor río del mundo» es un dato o una opinión?", "Una opinión", "«Mejor» valora y no se mide.")],
   [arith("Una fuente de ejemplo dice que un lago mide 120 kilómetros cuadrados y otra, 110. ¿Cuántos kilómetros cuadrados de diferencia hay?", "120-110", "Se resta una cifra de la otra."),
    E("Una página dice «Siempre llueve en Santiago en enero». ¿Qué señal de alerta tiene: afirmación absoluta o falta de título?", "Afirmación absoluta", "Usa la palabra «siempre»."),
    E("Si dos fuentes coinciden en un dato, ¿es más o menos confiable que si solo lo dice una?", "Más confiable", "La coincidencia lo respalda.")],
   [E("Dos estudiantes usan un dato. Ana dice «lo vi en un video sin autor». Beto dice «lo leí en un informe del Observatorio y coincide con otra institución». ¿Quién verificó mejor?", "Beto", "Contrastó dos fuentes."),
    E("Un artículo dice: «Este truco mágico cura todo». ¿Es una afirmación fiable o una exageración?", "Una exageración", "Ninguna cosa cura todo.")],
   [arith("Revisas 5 fuentes. 3 tienen autor y fecha; las otras no. ¿Cuántas fuentes no cumplen con esos dos datos?", "5-3", "Se restan las que sí cumplen."),
    E("Una fuente tiene autor, fecha y lenguaje objetivo, pero solo da opiniones sin datos. ¿Basta para usarla como dato?", "No", "Falta información comprobable.")]),
  [E("Para tu exposición sobre las abejas encuentras dos páginas: una de una universidad con fecha y autor, y otra anónima con exclamaciones. ¿Cuál usas primero?", "La de la universidad", "Tiene autor, fecha y origen identificable.")],
  [E("¿Qué es una fuente fidedigna?", "Una fuente confiable que se puede comprobar", "Su dato tiene respaldo."),
   E("¿Cuántas fuentes conviene contrastar como mínimo?", "2", "Para ver si coinciden."),
   E("¿Qué es una señal de alerta?", "Algo que hace dudar de una fuente", "Por ejemplo, no tener autor.")],
  ("Evalúa estas tres fuentes de ejemplo sobre «cuánto dura el día en verano»: A) «Instituto de Astronomía, 2023: en verano, en Santiago, hay cerca de 14 horas de luz». B) «Blog sin autor: ¡En verano el día dura siempre 20 horas!». C) «Libro escolar, autora identificada, 2022: en verano, en Santiago, hay más de 13 horas de luz». Escribe: cuál es la más confiable, cuáles coinciden y qué dato usarías.",
   "La A y la C son confiables: tienen institución o autora y fecha, y coinciden en un número cercano de horas de luz. La B tiene señales de alerta: sin autor, exclamaciones y la palabra «siempre». Usaría «cerca de 14 horas» citando el Instituto.",
   ["evalúa autor y fecha", "detecta señales de alerta", "contrasta fuentes"], ["evaluación de tres fuentes"], ["confiar en B", "no citar la fuente"], "Pide a otra persona que revise si tu justificación nombra autor, fecha y coincidencia."),
  "Elige una afirmación que hayas visto en redes y busca si otra fuente la confirma.",
  "Crea una lista de cinco señales de alerta con un ejemplo de cada una.")

L(OA22, 3,
  MAT_E,
  "Aprenderé a organizar una exposición con una progresión clara (inicio, desarrollo y cierre) y a usar conectores que guían al oyente.",
  ["Acoto mi tema.", "Uso fuentes confiables."],
  ["Una exposición tiene tres partes. En el inicio se saluda, se dice el tema y se despierta el interés con una pregunta, un dato o un ejemplo. En el desarrollo se explican las ideas principales, una por una, en un orden lógico. En el cierre se resume lo central y se deja una idea final o una invitación a la audiencia.",
   "La progresión temática es el orden en que avanzan las ideas. Puede seguir el tiempo (primero... después...), una causa y su efecto o un recorrido de lo general a lo particular. Para que la audiencia no se pierda, usa conectores que anuncien el avance: «en primer lugar», «luego», «además», «por ejemplo», «por último», «en conclusión».",
   "Una forma de comprobar tu orden es escribir cada idea en una tarjeta y ordenarlas. Pregúntate si cada tarjeta se entiende por lo anterior. Evita volver atrás o saltar. Y recuerda que el oyente no puede releer: repite la idea central al final de cada parte con una frase breve."],
  [("progresión temática", "orden en que avanzan las ideas de un texto"), ("conector", "palabra o expresión que une ideas, como «luego» o «por último»"), ("inicio", "parte que presenta el tema y capta la atención"), ("cierre", "parte final que resume y deja una idea final")],
  [("Ordenar ideas", "Ordena estas ideas de «Cómo se forma la lluvia»: A) el vapor sube y se enfría; B) el sol calienta el agua; C) caen gotas; D) el vapor forma nubes de gotitas.",
    ["Parte lo que ocurre primero: el sol calienta el agua.", "Luego el vapor sube y se enfría.", "Después se forman nubes y por último caen gotas."],
    "B, A, D, C"),
   ("Elegir conectores", "Completa: «___, el sol calienta el agua. ___, el vapor sube. ___, caen gotas.» Opciones: Primero, Luego, Por último.",
    ["La primera idea va con «Primero».", "La segunda, «Luego».", "La tercera, «Por último»."],
    "Primero, Luego, Por último")],
  [("Saltar de una idea a otra sin conectores.", "Se piensa que el oyente entiende solo.", "Usa conectores que anuncian el avance."),
   ("Empezar sin presentar el tema.", "Se asume que todos saben.", "Dice de qué trata en el inicio.")],
  ([E("En Lenguaje: ¿Cuáles son las tres partes de una exposición?", "Inicio, desarrollo y cierre", "Es la estructura básica."),
    E("¿Qué parte presenta el tema: el inicio o el cierre?", "El inicio", "Dice de qué trata."),
    E("¿«Por último» introduce el inicio o el final de la exposición?", "El final", "Anuncia la última idea.")],
   [E("Ordena: 1) Caen gotas. 2) El sol calienta el agua. ¿Cuál va primero?", "El sol calienta el agua", "Es el origen del proceso."),
    E("¿Qué conector sirve para dar un ejemplo: «por ejemplo» o «por último»?", "Por ejemplo", "Anuncia un caso concreto."),
    E("¿Dónde se resume lo central: en el desarrollo o en el cierre?", "En el cierre", "Es su función.")],
   [E("Ordena los pasos de hacer pan: A) hornear; B) amasar; C) mezclar harina y agua; D) dejar reposar la masa. ¿Cuál es el orden correcto?", "C, B, D, A", "Se mezcla, se amasa, reposa y se hornea."),
    E("Completa con «Primero, Luego o Por último»: «___, mezcla la harina; ___, agrega el agua; ___, hornea».", "Primero, Luego, Por último", "Sigue el orden de la receta."),
    E("Una exposición tiene un inicio, un desarrollo con tres ideas y un cierre. ¿Cuántas partes tiene su estructura básica?", "3", "Inicio, desarrollo y cierre; las tres ideas van dentro del desarrollo.")],
   [E("Ema inicia: «Hola, hoy hablaré de cómo se forma la lluvia. ¿Han visto cómo las nubes se oscurecen?». Rolando inicia: «Eeh, bueno, empiezo». ¿Quién abrió mejor?", "Ema", "Presentó el tema y despertó interés."),
    E("En un orden de causa y efecto, ¿qué va primero: la lluvia o el calor del sol que evapora el agua?", "El calor del sol", "Es la causa.")],
   [E("Un expositor dice: «En conclusión, el agua es vital para todos». ¿En qué parte de la exposición va esa frase: en el inicio o en el cierre?", "En el cierre", "«En conclusión» anuncia el resumen final."),
    E("Alguien escribe «Además» para pasar de la idea 1 a la 2. ¿Sirve para sumar una idea nueva o para anunciar el cierre?", "Para sumar una idea nueva", "«Además» agrega una idea y no cierra.")]),
  [E("Vas a exponer cómo se hace un cuaderno de apuntes: 1) doblar las hojas; 2) coserlas; 3) poner la tapa. ¿Qué conector usas para la última acción: «Por último» o «Primero»?", "Por último", "Marca el final de los pasos.")],
  [E("¿Qué hacen los conectores?", "Guían al oyente por las ideas", "Anuncian el avance."),
   E("¿Dónde se despierta el interés de la audiencia?", "En el inicio", "Con una pregunta o un dato."),
   E("¿Se puede repetir la idea central al final de cada parte?", "Sí", "Ayuda al oyente que no puede releer.")],
  ("Ordena y completa con conectores esta exposición sobre cómo se cuida una planta de interior: ideas: A) regar cuando la tierra esté seca; B) ponerla en un lugar con luz; C) limpiar las hojas. Escribe un inicio de dos oraciones, el desarrollo con conectores («Primero», «Luego», «Por último») y un cierre breve.",
   "Hola, hoy les explicaré cómo cuidar una planta de interior. ¿Saben qué necesita? Primero, hay que ponerla en un lugar con luz. Luego, se debe regar cuando la tierra esté seca. Por último, conviene limpiar las hojas. En resumen, luz, riego a tiempo y limpieza ayudan a que la planta viva bien.",
   ["tiene inicio con tema", "ordena las tres ideas con conectores", "cierra resumiendo"], ["texto de exposición"], ["olvidar el cierre", "usar siempre el mismo conector"], "Léelo en voz alta y comprueba que cada conector anuncia un avance."),
  "Organiza en tarjetas una exposición de tres ideas sobre tu deporte favorito.",
  "Escribe tres inicios distintos para la misma exposición: con pregunta, con dato y con ejemplo.")

L(OA22, 4,
  MAT_E,
  "Aprenderé a explicar conceptos clave con definiciones y ejemplos, a usar vocabulario variado y preciso y a evitar las muletillas.",
  ["Organizo una exposición.", "Uso conectores."],
  ["Un concepto clave es un término que la audiencia necesita entender para seguir la exposición. Para explicarlo, usa tres pasos: define con palabras simples, da un ejemplo y, si puedes, compara con algo cercano. Por ejemplo: «La fotosíntesis es el proceso por el que las plantas fabrican su alimento con luz. Es como una cocina que usa el sol en vez del fuego».",
   "El vocabulario preciso evita decir «cosa» o «eso». En vez de «la cosa que sube», di «el vapor». El vocabulario variado evita repetir la misma palabra, pero sin cambiar el sentido. Revisa que cada término técnico se explique la primera vez que aparece.",
   "Las muletillas son palabras o sonidos de relleno que se repiten sin aportar: «eeh», «o sea», «como que», «cachai», «ya po». No son un error grave, pero en exceso cansan y restan claridad. Para reducirlas, haz pausas silenciosas en lugar de rellenar y ensaya el discurso en voz alta. Una pausa breve suena más segura que un «eeh»."],
  [("concepto clave", "término que la audiencia necesita entender"), ("vocabulario preciso", "palabras exactas que nombran lo que se quiere decir"), ("muletilla", "palabra de relleno que se repite sin aportar significado"), ("analogía", "comparación entre dos cosas distintas para explicar mejor")],
  [("Definir con ejemplo", "Explica «condensación» a tu curso.",
    ["Defino: paso del vapor de agua a gotitas líquidas.", "Doy un ejemplo: el vidrio frío de una ventana se empaña.", "Comparo si sirve: es como las gotas de un espejo del baño."],
    "La condensación es el paso del vapor a líquido; por ejemplo, las gotitas en una ventana fría"),
   ("Contar muletillas", "Cuenta las muletillas de: «O sea, la fotosíntesis, eeh, es como que, o sea, cuando las plantas, eeh, hacen su alimento».",
    ["Busco «o sea»: aparece dos veces.", "Busco «eeh»: aparece dos veces.", "Busco «como que»: una vez. Total 5."],
    "5")],
  [("Usar un término técnico sin explicarlo.", "Se supone que todos lo conocen.", "Defínelo la primera vez que aparece."),
   ("Rellenar los silencios con muletillas.", "Se teme a las pausas.", "Haz una pausa en silencio.")],
  ([E("¿Qué incluye explicar un concepto: definición y ejemplo o solo el nombre?", "Definición y ejemplo", "Así se entiende."),
    E("¿«Eeh» es una muletilla o un concepto?", "Una muletilla", "Es un sonido de relleno."),
    E("¿Qué es mejor decir: «la cosa que sube» o «el vapor»?", "El vapor", "Es una palabra precisa.")],
   [E("Explica con ejemplo: «El vidrio frío de una ventana se empaña». ¿Qué concepto ilustra: condensación o evaporación?", "Condensación", "El vapor se convierte en gotitas."),
    E("¿Qué hacer en lugar de rellenar con «eeh»: una pausa en silencio o hablar más rápido?", "Una pausa en silencio", "Suena más seguro."),
    E("¿Una analogía compara dos cosas parecidas o idénticas?", "Parecidas", "Ayuda a entender lo desconocido con lo conocido.")],
   [E("¿Cuántas muletillas hay en «Bueno, o sea, la lluvia, eeh, o sea, viene de las nubes»? Cuenta «o sea» y «eeh».", "3", "Hay dos «o sea» y un «eeh»."),
    E("Define con una analogía el corazón: «Es como una bomba que ___ la sangre». ¿Qué palabra completa: mueve o guarda?", "mueve", "El corazón impulsa la sangre."),
    E("¿Cuál es más variado y preciso: «La cosa es grande» o «El edificio es enorme»?", "El edificio es enorme", "Nombra qué es y cómo es.")],
   [E("Ana explica «ecosistema» como «eso donde viven cosas». Beto lo explica como «un lugar donde los seres vivos se relacionan entre sí y con el entorno». ¿Quién fue más preciso?", "Beto", "Define con palabras exactas."),
    arith("Una exposición dura 2 minutos y tiene 12 muletillas. ¿Cuántas muletillas hay por minuto?", "12//2", "Se divide el total entre los minutos.")],
   [arith("Una persona dice 18 muletillas en 3 minutos. ¿Cuántas por minuto?", "18//3", "Se divide el total entre los minutos."),
    E("Si defines «sequía» como «poca lluvia» y das el ejemplo «campos secos por meses», ¿cumples los dos pasos de definición y ejemplo?", "Sí", "Hay definición y ejemplo.")]),
  [E("Exponiendo sobre el reciclaje dices «compostaje» sin explicarlo. ¿Qué debes agregar: una definición o un chiste?", "Una definición", "El término debe entenderse.")],
  [E("¿Cuántos pasos recomienda la clase para explicar un concepto?", "3", "Definir, ejemplificar y comparar."),
   E("¿Qué es una muletilla?", "Una palabra de relleno que se repite", "No aporta significado."),
   E("¿Qué sustituye a una muletilla en un buen discurso?", "Una pausa", "Da tiempo para pensar.")],
  ("Elige uno de estos conceptos: «sequía», «reciclaje», «ecosistema». Escribe en cuatro oraciones: 1) su definición; 2) un ejemplo; 3) una analogía; 4) una frase final. Luego léelo en voz alta sin muletillas y pide a otra persona que cuente las que escucha.",
   "El reciclaje es transformar residuos en nuevos productos. Por ejemplo, el papel usado se vuelve cartón. Es como darle una segunda vida a los objetos. En resumen, reciclar ayuda a cuidar los recursos. Conté cero muletillas.",
   ["define con palabras simples", "da un ejemplo claro", "propone una analogía", "reduce las muletillas"], ["cuatro oraciones", "conteo de muletillas"], ["usar «cosa» y «eso»", "olvidar la analogía"], "Pide que levanten un dedo por cada muletilla y compara con tu conteo."),
  "Explica un concepto de tu colegio a alguien de tu casa y pide que cuente tus muletillas.",
  "Escribe tres definiciones de conceptos que te gusten, cada una con ejemplo.")

L(OA22, 5,
  MAT_E,
  "Aprenderé a diseñar un apoyo visual útil para la exposición: pocas palabras, una idea por lámina y una relación directa con lo que se explica.",
  ["Organizo mis ideas.", "Explico conceptos con ejemplos."],
  ["Un apoyo visual (lámina, cartulina, diagrama) ayuda a la audiencia a seguir lo que dices. Debe apoyar, no reemplazar, tu discurso. Un buen apoyo cumple cuatro reglas. Primero, una idea por lámina. Segundo, pocas palabras: como guía, no más de seis líneas ni más de seis palabras por línea (la regla del 6 por 6). Tercero, letra grande y con buen contraste. Cuarto, imágenes que se relacionen directamente con lo que explicas.",
   "Un error común es poner todo el texto del discurso en la lámina y leerlo. Si la audiencia lee, deja de escucharte. Otro error es usar imágenes decorativas que no tienen que ver con la idea. Una buena imagen explica algo: un diagrama del ciclo del agua, una foto de un volcán señalando sus partes.",
   "Para probar tu lámina, mírala a unos tres metros: ¿se lee? Luego pregúntate: si le quito esta imagen, ¿se pierde algo importante? Si no, sobra. Un dato de ejemplo en un gráfico sencillo se entiende mejor que muchos números en una frase. Nombra siempre la fuente del dato en un lugar pequeño de la lámina."],
  [("apoyo visual", "imagen, lámina o diagrama que acompaña una exposición"), ("contraste", "diferencia entre el color del texto y el del fondo que permite leer"), ("regla del 6 por 6", "guía de seis líneas como máximo y seis palabras por línea como máximo"), ("diagrama", "dibujo simple que muestra partes o pasos de algo")],
  [("Revisar una lámina", "Una lámina tiene 9 líneas con 14 palabras cada una. ¿Cumple la regla del 6 por 6?",
    ["Reviso las líneas: 9 es más de 6.", "Reviso las palabras: 14 es más de 6.", "No cumple."],
    "No cumple"),
   ("Elegir la imagen", "Explicas el ciclo del agua. ¿Qué imagen sirve: un diagrama con flechas del agua que sube y cae o una foto de un perro?",
    ["La imagen debe relacionarse con lo que explico.", "El diagrama muestra el proceso.", "La foto es decorativa."],
    "El diagrama con flechas")],
  [("Escribir todo el discurso en la lámina.", "Se usa como libreto.", "Anota solo palabras clave."),
   ("Usar imágenes que solo decoran.", "Se busca que se vea bonito.", "Elige imágenes que expliquen la idea.")],
  ([E("Según la regla del 6 por 6, ¿cuántas líneas como máximo debe tener una lámina?", "6", "La regla pone ese límite."),
    E("¿Una lámina debe apoyar o reemplazar tu discurso?", "Apoyar", "No es un libreto."),
    E("¿Qué letra se lee mejor desde lejos: grande o pequeña?", "Grande", "La audiencia está a varios metros.")],
   [E("Una lámina tiene 4 líneas con 5 palabras cada una. ¿Cumple la regla del 6 por 6?", "Sí", "4 y 5 son menos de 6."),
    E("¿Qué imagen sirve para explicar las partes de un volcán: un dibujo con las partes marcadas o una foto de un paisaje cualquiera?", "Un dibujo con las partes marcadas", "Se relaciona con lo que se explica."),
    E("Si quito una imagen y no se pierde nada importante, ¿esa imagen sobra o es indispensable?", "Sobra", "No aporta a la idea.")],
   [arith("Una lámina tiene 8 líneas. La regla del 6 por 6 permite hasta 6. ¿Cuántas líneas hay que quitar?", "8-6", "Se resta el máximo permitido."),
    E("Una lámina tiene texto gris claro sobre fondo blanco. ¿Tiene buen contraste?", "No", "Se lee con dificultad."),
    E("Una lámina tiene 5 líneas y cada línea tiene 6 palabras. ¿Cumple la regla del 6 por 6?", "Sí", "No supera 6 líneas ni 6 palabras por línea.")],
   [E("Ana pone en su lámina todo el discurso y lo lee. Beto pone cuatro palabras clave y una imagen del proceso. ¿Quién usó mejor el apoyo visual?", "Beto", "Su lámina apoya sin reemplazar."),
    E("Un gráfico de barras sencillo con la lluvia mensual de ejemplo, ¿se entiende mejor que doce cifras en una frase?", "Sí", "Permite comparar de un vistazo.")],
   [E("Una exposición tiene 3 ideas y cada una tiene una lámina. ¿Cuántas láminas necesita como mínimo?", "3", "Una idea por lámina."),
    E("Una lámina tiene una imagen bonita de un paisaje que no se menciona en la exposición. ¿Es una imagen funcional o decorativa?", "Decorativa", "No explica nada de lo expuesto.")]),
  [E("Preparas una lámina para explicar el ciclo del agua con las palabras «evaporación», «condensación» y «precipitación», más un diagrama. ¿Cumple el 6 por 6?", "Sí", "Tiene pocas palabras y una sola idea.")],
  [E("¿Cuál es la primera regla de un buen apoyo visual?", "Una idea por lámina", "Evita el exceso."),
   E("¿Qué es el contraste?", "La diferencia entre el color del texto y el fondo", "Permite leer bien."),
   E("¿A qué distancia conviene probar si se lee tu lámina?", "A unos tres metros", "Es una distancia razonable para comprobar que se lee.")],
  ("Diseña una lámina para explicar «las fases de la Luna» con estas palabras: «Luna nueva», «cuarto creciente», «Luna llena», «cuarto menguante». Escribe (o dibuja) cómo sería: el título, las palabras clave y la imagen que usarías. Verifica la regla del 6 por 6 y el contraste.",
   "Título: Fases de la Luna. Imagen: cuatro círculos con la parte iluminada creciendo y luego disminuyendo. Palabras: Luna nueva, cuarto creciente, Luna llena, cuarto menguante (4 líneas de 2 palabras). Letra negra sobre fondo blanco, cumple el 6 por 6.",
   ["una idea", "pocas palabras", "imagen funcional", "buen contraste"], ["lámina dibujada o descrita"], ["escribir un párrafo largo", "usar imagen decorativa"], "Muéstrala a unos tres metros y pide a otra persona que lea los títulos."),
  "Diseña una lámina de cuatro líneas para un tema que domines.",
  "Rediseña una lámina cargada de texto hasta cumplir la regla del 6 por 6.")

L(OA22, 6,
  MAT_E,
  "Aprenderé a ensayar una exposición cuidando el tiempo, a presentarla con seguridad y a dar y recibir retroalimentación específica y amable.",
  ["Preparo mi exposición.", "Diseño un apoyo visual."],
  ["Una exposición se mejora ensayando en voz alta. Ensayar sirve para tres cosas: comprobar el tiempo, detectar muletillas y practicar la voz. Como guía, un discurso a ritmo claro tiene entre 100 y 130 palabras por minuto. Si tu texto tiene 390 palabras, a 130 palabras por minuto dura 3 minutos. Si el tiempo asignado es menor, hay que recortar.",
   "Durante la presentación, mira a la audiencia, usa el apoyo visual solo para señalar, controla las muletillas y respeta el orden. Si te equivocas, no te detengas: continúa con calma. Después, recibirás retroalimentación. Una retroalimentación útil es específica (dice qué y cuándo), observable (se basa en lo que se vio u oyó) y amable. Un formato sencillo: dos aciertos y una mejora.",
   "Un ejemplo vago: «Estuvo bien». Un ejemplo específico: «Tu ejemplo del vapor en la ventana fue claro; podrías mirar más a la audiencia durante la segunda idea». Al recibirla, escucha sin interrumpir, agradece y elige una mejora para el próximo ensayo. Así, cada presentación te prepara para la siguiente."],
  [("ensayar", "practicar en voz alta antes de presentar"), ("palabras por minuto", "medida de la velocidad del discurso"), ("retroalimentación", "comentario que ayuda a mejorar un trabajo"), ("específica", "que dice con precisión qué se hizo y dónde")],
  [("Calcular el tiempo", "Tu texto tiene 390 palabras y hablas a 130 palabras por minuto. ¿Cuánto dura?",
    ["Divido las palabras entre las palabras por minuto.", "390 ÷ 130 = 3.", "Dura 3 minutos."],
    "3 minutos"),
   ("Dar retroalimentación", "¿Cuál es mejor: «Estuvo bien» o «Tu ejemplo del vapor fue claro; mira más a la audiencia en la segunda idea»?",
    ["Reviso si es específica.", "La segunda dice qué y qué mejorar.", "La primera es vaga."],
    "La segunda")],
  [("No ensayar en voz alta.", "Se piensa que leer en silencio basta.", "Ensaya con tiempo y voz reales."),
   ("Dar retroalimentación vaga o hiriente.", "Se dice «estuvo mal».", "Da dos aciertos y una mejora específica.")],
  ([E("En Lenguaje: ¿Para qué sirve ensayar en voz alta?", "Para comprobar tiempo y mejorar la voz", "Se detectan problemas antes."),
    E("¿«Estuvo bien» es una retroalimentación específica o vaga?", "Vaga", "No dice qué estuvo bien."),
    E("¿Qué formato de retroalimentación propone la clase: dos aciertos y una mejora o un insulto?", "Dos aciertos y una mejora", "Es útil y amable.")],
   [arith("Tu texto tiene 260 palabras y lo dices a 130 palabras por minuto. ¿Cuántos minutos dura?", "260//130", "Se divide el total entre la velocidad."),
    E("Si te equivocas durante la presentación, ¿qué haces: continúas con calma o abandonas?", "Continúas con calma", "Mantiene la seguridad."),
    E("¿La retroalimentación debe basarse en lo observable o en lo que se supone de la persona?", "En lo observable", "Dice lo que se vio u oyó.")],
   [arith("Un discurso dura 4 minutos y tiene 480 palabras. ¿Cuántas palabras por minuto son?", "480//4", "Se divide el total entre los minutos."),
    E("Tienes 3 minutos y tu texto tiene 450 palabras a 130 por minuto. ¿Cabe sin recortar?", "No", "Dura más de 3 minutos (450 ÷ 130 es más de 3)."),
    E("¿Cuál es una mejora específica: «Habla mejor» o «Haz una pausa antes de la segunda idea»?", "Haz una pausa antes de la segunda idea", "Indica qué y dónde.")],
   [E("Ana recibe «Tu inicio con una pregunta captó mi atención. Los números de la lámina eran pequeños». ¿Cuántos aciertos y cuántas mejoras tiene el comentario?", "Un acierto y una mejora", "El primer comentario es un acierto y el segundo, una mejora."),
    E("¿Quién recibe mejor la retroalimentación: quien escucha sin interrumpir o quien discute cada punto?", "Quien escucha sin interrumpir", "Entiende los comentarios y elige mejoras.")],
   [arith("Un texto de 520 palabras debe caber en 5 minutos. ¿A cuántas palabras por minuto tendrías que hablar?", "520//5", "Se divide el total entre los minutos."),
    E("Hablar a 104 palabras por minuto, ¿está dentro del rango recomendado de 100 a 130?", "Sí", "104 está entre 100 y 130.")]),
  [E("Presentas una exposición de 5 minutos a tu curso y tu texto tiene 650 palabras. A 130 palabras por minuto, ¿cuánto dura?", "5 minutos", "650 ÷ 130 = 5.")],
  [E("¿Entre qué valores de palabras por minuto sugiere la clase hablar?", "Entre 100 y 130", "Mantiene un ritmo claro."),
   E("¿Qué debe ser una retroalimentación útil: específica, observable y amable?", "Específica, observable y amable", "Esas son las tres características."),
   E("¿Qué haces con la retroalimentación: eliges una mejora o la olvidas?", "Eliges una mejora", "Así avanzas en el próximo ensayo.")],
  ("Prepara una exposición de 2 minutos sobre «Cómo cuidar una planta de interior». Escribe tu texto (aprox. 240 palabras), ensáyalo con un reloj, anota cuánto tardaste y cuántas muletillas contaste. Pide a una persona dos aciertos y una mejora específica y regístralos.",
   "Texto de 240 palabras; ensayé en 2 minutos 10 segundos; conté 4 muletillas. Retroalimentación: 1) tu inicio con pregunta atrajo; 2) la explicación del riego fue clara. Mejora: reduce las muletillas «o sea».",
   ["ensaya con tiempo medido", "cuenta muletillas", "recibe dos aciertos y una mejora específica"], ["registro del ensayo", "retroalimentación"], ["no medir el tiempo", "aceptar «estuvo bien»"], "Repite el ensayo aplicando la mejora y compara."),
  "Ensaya en voz alta un texto de una página y anota cuánto tardas.",
  "Prepara una pauta de retroalimentación de cuatro criterios para tus compañeros.")
